(()=>{'use strict';const store=window.NexusStore,$=id=>document.getElementById(id);const names={zeugnis:'Zeugnis',bewertung:'Bewertungsbogen',exit:'Exitgespräch',protokoll:'Übergabe & Rückgabe',checklisten:'Checkliste'},statuses={draft:'Entwurf',review:'In Prüfung',approved:'Freigegeben'};const message=s=>$('managerStatus').textContent=s;
function button(text,handler){const b=document.createElement('button');b.type='button';b.textContent=text;b.onclick=handler;return b;}
function render(){try{const all=store.read(),trash=$('showTrash').checked,query=$('searchDraft').value.trim().toLowerCase(),type=$('filterType').value,status=$('filterStatus').value;const records=all.filter(d=>!!d.deletedAt===trash&&(!type||d.type===type)&&(!status||d.status===status)&&(!query||d.title.toLowerCase().includes(query))).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));const list=$('draftsList');list.replaceChildren();$('draftCount').textContent=records.length+' Vorgänge';if(!records.length){const el=document.createElement('div');el.className='empty-state';el.textContent=trash?'Der Papierkorb ist leer.':'Keine passenden Entwürfe. In einem Werkzeug „Entwurf speichern“ wählen.';list.append(el);}for(const d of records){const card=document.createElement('article');card.className='draft-card';const badge=document.createElement('span');badge.className='status-badge '+d.status;badge.textContent=statuses[d.status];const h=document.createElement('h2');h.textContent=d.title;const meta=document.createElement('p');meta.className='ws-meta';meta.textContent=names[d.type]+' · '+new Date(d.updatedAt).toLocaleString('de-DE');const review=document.createElement('p');review.className='ws-meta';review.textContent=d.reviewer?'Prüfung / Freigabe: '+d.reviewer+(d.reviewedAt?' · '+new Date(d.reviewedAt).toLocaleString('de-DE'):''):'';const actions=document.createElement('div');actions.className='ws-actions';if(trash)actions.append(button('Wiederherstellen',()=>act(()=>store.restore(d.id))));else{const link=document.createElement('a');link.className='action-link';link.textContent='Öffnen';link.href='./tools/'+d.type+'.html?draft='+encodeURIComponent(d.id);actions.append(link,button('Duplizieren',()=>act(()=>store.copy(d.id))),button('In Papierkorb',()=>act(()=>store.trash(d.id))));}card.append(badge,h,meta,review,actions);list.append(card);}}catch(err){message(err.message);}}
function act(fn){try{fn();render();message('Änderung gespeichert.');}catch(e){message(e.message);}}
['searchDraft','filterType','filterStatus','showTrash'].forEach(id=>$(id).addEventListener('input',render));
$('backupAll').onclick=()=>{try{const blob=new Blob([JSON.stringify(store.backup(),null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='neXus_Workspace_Sicherung.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),15000);message('Sicherung einschließlich Papierkorb bereitgestellt.');}catch(e){message(e.message);}};
$('importBackup').onclick=()=>$('backupFile').click();$('backupFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const n=store.importBackup(JSON.parse(await f.text()));render();message(n+' Vorgänge importiert. Vorhandene Entwürfe wurden nicht überschrieben.');}catch(err){message(err.message);}finally{e.target.value='';}};render();})();
